rules.logic:
// Avoid duplicating the widget on re-runs
if (element.parentNode.querySelector('#post-community-sidebar')) return;

// Grab the original "Post to the help community" anchor
var originalOption = document.querySelector('.need-more-help-option');
if (!originalOption) return;

// Build a self-contained sidebar card
var card = document.createElement('div');
card.id = 'post-community-sidebar';
card.style.cssText = [
  'display:flex',
  'align-items:center',
  'gap:12px',
  'margin:12px 0 20px',
  'padding:12px 16px',
  'background:#f0f7ff',
  'border:1.5px solid #4285f4',
  'border-radius:10px',
  'text-decoration:none',
  'color:inherit',
  'cursor:pointer',
  'box-shadow:0 2px 6px rgba(66,133,244,.15)'
].join(';');

// Clone the SVG icons container
var svgContainer = originalOption.querySelector('.need-more-help-option__svg-container');
if (svgContainer) {
  var svgClone = svgContainer.cloneNode(true);
  svgClone.style.cssText = 'flex-shrink:0;width:44px;height:44px';
  card.appendChild(svgClone);
}

// Build the text block
var textDiv = document.createElement('div');
textDiv.style.cssText = 'display:flex;flex-direction:column;gap:2px';

var title = document.createElement('span');
title.textContent = 'Post to the help community';
title.style.cssText = 'font-size:14px;font-weight:600;color:#1a73e8';

var snippet = document.createElement('span');
snippet.textContent = 'Get answers from community members';
snippet.style.cssText = 'font-size:12px;color:#555';

textDiv.appendChild(title);
textDiv.appendChild(snippet);
card.appendChild(textDiv);

// Make the card a clickable link mirroring the original href
var href = originalOption.getAttribute('href');
if (href) {
  card.addEventListener('click', function() { window.location.href = href; });
}

// Insert right after the h1
element.parentNode.insertBefore(card, element.nextSibling);
